118:      pill.textContent = item.state === "read" ? "Read" : "To read";
120:      var btn = document.createElement("button");
121:      btn.className = "act" + (item.state === "toread" ? " primary" : "");
122:      btn.textContent = item.state === "toread" ? "Mark read" : "Move back to to-read";
123:      btn.onclick = function(){ item.state = item.state === "toread" ? "read" : "toread"; render(); };
127:        var pill2 = document.createElement("span"); pill2.className="statepill toread"; pill2.textContent="In reading list"; wrap.appendChild(pill2);
128:        var done = document.createElement("button"); done.className="act primary"; done.textContent="Done"; done.onclick=function(){ item.done=true; item.inList=false; render(); }; wrap.appendChild(done);
130:        var add = document.createElement("button"); add.className="act"; add.textContent="＋ Reading list"; add.onclick=function(){ item.inList=true; item.done=false; render(); }; wrap.appendChild(add);
142:    if (MODE === "b" && view === "list") count.textContent = vis.length + " in your reading list";
